    void rollback(int state = -1) {
        if (state == -1) state = inner_snap;
#ifndef SKIP_RUNTIME_CHECKS
        if (state < 0 || state > get_state()) throw std::out_of_range("RollbackUnionFind: state");
#endif
        while (get_state() > state) undo_last();
