 if(argc!=4)return 1;
 const int n=std::atoi(argv[1]),mode=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 std::mt19937 rng(61022);std::vector<std::pair<int,int>> edges;
 if(mode==0){for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)edges.emplace_back(i,i+step);}
 if(mode==1){for(int i=1;i<n;++i)edges.emplace_back(0,i);}
 if(mode>=2&&mode<=3){for(int i=0;i<n;++i)edges.emplace_back(0,n-1);}
 if(mode==4){for(int i=0;i<n;++i)edges.emplace_back(int(rng()%n),int(rng()%n));}
