  for(auto [a,b]:edges){checksum+=uf.unite(a,b);if(mode==3)uf.undo();}
  if(mode==0){for(std::size_t i=0;i<edges.size();++i)uf.undo();}else uf.rollback(base);
  checksum+=static_cast<unsigned>(uf.get_state())+static_cast<unsigned>(uf.component_count());
 }
