#include SOURCE
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <utility>
#include <vector>
static std::size_t checks=0;
static void require(bool b){++checks;if(!b)std::abort();}
struct Model{
 std::vector<int> label;std::vector<std::vector<int>> history;int snap=0;
 explicit Model(int n):label(n){std::iota(label.begin(),label.end(),0);}
 int count(int a)const{return static_cast<int>(std::count(label.begin(),label.end(),label[a]));}
 bool unite(int a,int b){history.push_back(label);int x=label[a],y=label[b];if(x==y)return false;if(count(a)<count(b))std::swap(x,y);for(auto& v:label)if(v==y)v=x;return true;}
 void undo(){label=history.back();history.pop_back();snap=std::min(snap,int(history.size()));}
 void rollback(int n){if(n<0)n=snap;while(int(history.size())>n)undo();snap=std::min(snap,n);}
};
int main(){
 std::mt19937_64 rng(20261022);
 for(int n:{1,2,3,8,16,33,64}){
  RollbackUnionFind uf(n);Model m(n);
  for(int step=0;step<4000;++step){
   int a=int(rng()%n),b=int(rng()%n);int op=int(rng()%10);
   if(op<5){bool x=uf.unite(a,b),y=m.unite(a,b);require(x==y);}
   else if(op==5&&!m.history.empty()){uf.undo();m.undo();}
   else if(op==6){int state=int(rng()%(m.history.size()+1));uf.rollback(state);m.rollback(state);}
   else if(op==7){uf.snapshot();m.snap=int(m.history.size());}
   else if(op==8){uf.rollback();m.rollback(-1);}
   else{auto copy=uf;copy.unite(a,b);require(uf.get_state()==int(m.history.size()));}
   require(uf.size()==n);require(uf.get_state()==int(m.history.size()));int count=0;
   for(int i=0;i<n;++i){require(uf.find(i)==m.label[i]);require(uf.size(i)==m.count(i));count+=m.label[i]==i;}
   require(uf.component_count()==count);
   for(int k=0;k<5;++k){a=int(rng()%n);b=int(rng()%n);require(uf.same(a,b)==(m.label[a]==m.label[b]));}
   if(step%100==0){std::vector<std::vector<int>> groups;for(int i=0;i<n;++i)if(m.label[i]==i){groups.emplace_back();for(int j=0;j<n;++j)if(m.label[j]==i)groups.back().push_back(j);}require(uf.groups()==groups);}
  }
 }
 RollbackUnionFind a(0);require(a.size()==0&&a.get_state()==0&&a.groups().empty());
 std::printf("PASS %zu\n",checks);
}

