 s=s.replace('inner_snap(std::exchange(other.inner_snap, 0)), components_','inner_snap(std::exchange(other.inner_snap, 0)), state_(std::exchange(other.state_, 0)), components_')
 s=s.replace('inner_snap = std::exchange(other.inner_snap, 0); components_','inner_snap = std::exchange(other.inner_snap, 0); state_ = std::exchange(other.state_, 0); components_')
