#include <cstddef>
#include <iostream>
#include <utility>
#include <vector>
struct Node{int left=0,right=0,value=-1;};
struct PersistentDSU{
 int count;std::vector<Node> nodes{Node{}};
 explicit PersistentDSU(int n):count(n){}
 int get(int node,int index)const{
  int l=0,r=count;
  while(node&&r-l>1){int m=l+(r-l)/2;if(index<m){node=nodes[node].left;r=m;}else{node=nodes[node].right;l=m;}}
  return node?nodes[node].value:-1;
 }
 int set(int original,int l,int r,int index,int value){
  const auto node=static_cast<int>(nodes.size());const auto copy=nodes[original];nodes.push_back(copy);
  if(r-l==1)nodes[node].value=value;
  else{const auto m=l+(r-l)/2;if(index<m){const auto child=set(nodes[node].left,l,m,index,value);nodes[node].left=child;}else{const auto child=set(nodes[node].right,m,r,index,value);nodes[node].right=child;}}
  return node;
 }
 std::pair<int,int> leader(int root,int vertex)const{int value=get(root,vertex);while(value>=0){vertex=value;value=get(root,vertex);}return{vertex,value};}
 int join(int root,int a,int b){auto [x,sx]=leader(root,a);auto [y,sy]=leader(root,b);if(x==y)return root;if(sx>sy){std::swap(x,y);std::swap(sx,sy);}const auto next=set(root,0,count,x,sx+sy);return set(next,0,count,y,x);}
};
int main(){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);int n,q;if(!(std::cin>>n>>q))return 0;PersistentDSU dsu(n);std::vector<int> versions(static_cast<std::size_t>(q)+1);for(int i=1;i<=q;++i){int type,base,a,b;std::cin>>type>>base>>a>>b;const auto root=versions[base+1];if(type==0)versions[i]=dsu.join(root,a,b);else std::cout<<(dsu.leader(root,a).first==dsu.leader(root,b).first)<<'\n';}}

